\section{Preliminaries}\label{sec:Prelim}

We denote by $G=(V,E, w)$ the input digraph where $w$ is the weight function mapping each edge to a number in the reals and define $n=|V|$ and $m = |E|$. In this article, we define $H \subseteq G$ to refer to $H$ being a vertex-induced subgraph of $G$, i.e. $H = G[V \setminus D]$ for some $D \subseteq V$. We also slightly abuse notation and write $G \setminus D$ for $D \subseteq V$ to denote $G[V \setminus D]$. We let the graph $H$ with edge directions reversed be denote by $\overleftarrow{H}$.

The \emph{weight} of a path $\pi$ in an edge-weighted graph $G$ is the sum of weights of its edges. We let $w$ denote the weight function that maps each path in $\pi$ to its weight. We use $\nil$ to denote the empty path of weight $\infty$. Given two paths $\pi_1 = \langle u_1, u_2, \ldots, u_p \rangle$ and $\pi_2 = \langle v_1, v_2 \ldots, v_q \rangle$ in $G$ where $u_p = v_1$, denote by $\pi_1 \circ \pi_2$ the concatenated path $\langle u_1, u_2 \ldots, u_p =v_1, v_2, \ldots, v_q\rangle$. For any path $\pi$, we define $\pi\circ\nil = \nil\circ \pi = \nil$.

Let $\pi_{s,t}$ be a path starting in vertex $s$ and ending in vertex $t$. Then $\pi_{s,t}$ is a \emph{shortest path} in $G$ if its sum of edge weights is minimized over all paths from $s$ to $t$ in $G$. We denote the weight of a shortest path from $s$ to $t$ by $\mathbf{dist}_G(s,t)$. 

We say $\pi_{s,t}$ is the shortest path from $s$ to $t$ \emph{through} $C \subset V$, if $\pi_{s,t}$ is the path of minimum weight from $s$ to $t$ that contains a vertex in $C$. We further say a path $\pi_{s,t}$ has hop $h$ or is a \emph{$h$-hop-restricted path} in $G$ if it consists of at most $h$ edges. We denote by $\mathbf{dist}_G^h(s,t)$ the weight of the $h$-hop-restricted shortest path from $s$ to $t$. Finally, we define the notion of an \emph{improving} shortest path $\pi_{s,t}$ in $G$ with regard to $H \subseteq G$ to be a path of weight at most $\mathbf{dist}_{H}(s,t)$. We often combine these notions, saying, for example, that $\pi_{s,t}$ is an $h$-hop-improving shortest path through $C$ in $G$ with respect to $G \setminus D$ to refer to a path $\pi_{s,t}$ that is in $G$ and has weight at most equal to the shortest path between $s$ and $t$ of hop $h$ that contains a vertex in $C$ in $G \setminus D$.

\subsection{A Batch Deletion Data Structure with Efficient Preprocessing Time}

Let $i_h = \lceil\log_{3/2} h\rceil$ and let $h_i = (3/2)^i$, for $i = 0,\ldots,i_h$ throughout the rest of the article.

\subsection{A Simple and Space-Efficient Deterministic Data Structure}
\label{subsec:spaceEfficientDet}

\begin{algorithm}
\caption{$\textsc{BellmanFordSpaceEfficient}(s, H, h_i = (3/2)^i)$}
\label{alg:detBellmanFord}
\KwIn{A graph $H$ and source $s \in H(V)$, an integer $h_i = (3/2)^i \geq 1$.}
\KwOut{The algorithm returns a set of $h_i$-hop-improving shortest paths $\{\pi^i_{s,t}\}_{t\in V}$ each of length $O(h_i)$ that can be represented in space $\tilde{O}(n)$. }

\BlankLine

$H' \gets H; j \gets i$\;
\For{$j \gets i$ down to $0$}{
    $\{\tau^j_{s,t}\}_{t\in V} \gets \textsc{BellmanFord}(s, H^j, h_j)$\;

    \If{$h_j > 3$}{
        Compute an integer $\textsc{Rad}^{j}(s) \in (\frac 13 h_j,\frac 23 h_j)$ that minimizes the size of  $\textsc{Separator}^j(s) = \{x \in V \vert |\pi^{j}_{s,x}| = \textsc{Rad}^{j}(s)\}$ \label{lne:deleteSeparator}
    }\Else{$\textsc{Separator}^j(s) \gets V$}

    \ForEach(\label{lne:storePaths}){$x \in \textsc{Separator}^j(s)$}{
        Store path $\tau^{j}_{s,x}$\;
        $w'(s,t) \gets w(\tau^{j}_{s,x})$
    }
}
\end{algorithm}

The algorithm runs in iterations executed by the for-loop where the index $j$ is initially set to $i$ and decreased after every iteration until it is $0$. In each iteration, we compute the hop-$h_j$-restricted shortest paths $\{\tau^j_{s,t}\}_{t\in V}$ on the graph $H'$. For the sake of analysis, we let $H^j$ be the graph of $H'$ at the start of iteration $j$. After computing the paths on $H^j$, we compute a separator set $\textsc{Separator}^j(s)$ that contains all vertices whose shortest path from $s$ has length $\textsc{Rad}^j(s)$ which is taken to be strictly between $\frac 13 h_j$ and $\frac 23 h_j$ (except for very small $h_j$ where we chose the separator set to be $V$). 

In the foreach-loop in line \ref{lne:storePaths}, we store for every vertex $x$ in the hitting set $\textsc{Separator}^j(s)$, the $h_j$-hop-restricted shortest path $\tau^j_{s,x}$. If the first edge on the path represents a subpath from a higher level, we add a pointer to the subpath. Then, we update $H^j$ by setting the weight of the edge from $s$ to $x$ to the weight of $\tau^j_{s,x}$. Observe that after the foreach-loop finished, all paths $\tau^j_{s,t}$, for any $t \in V(H)$, can be mapped to a path in $H'$ of same weight and of length at most $h_{j-1} = \frac 23 h_j$ and observe that this graph is graph $H^{j-1}$. 

Finally, we store the paths $\pi^i_{s,t}$ by a pointer to $\tau^0_{s,t}$. Observe that each path $\tau^0_{s,t}$ might then be unpacked to an $h_i$-improving shortest path in $H$ by replacing the first edge on a path by the corresponding subpath on a higher level.
```


